    ("actual-native-Choose-source-checks-close-at-submission",()=>Run(()=>{using var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("PeelLinuxAppSource.c")??throw new Exception("Actual selected native source resource missing.");using var reader=new StreamReader(stream);string source=reader.ReadToEnd();int begin=source.IndexOf("static void choose(",StringComparison.Ordinal);Check(begin>=0);int end=source.IndexOf('\n',begin);string body=source[begin..end];int guard=body.IndexOf("if (app.closing || !app.window) return;",StringComparison.Ordinal);int launch=body.IndexOf("peel_host_choose(app.window, FALSE)",StringComparison.Ordinal);Check(guard>=0&&launch>guard); })),
