int failures=0;foreach(var(name,run)in cases){try{await run().WaitAsync(TimeSpan.FromSeconds(4));Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+" "+e.GetType().Name);}}Console.WriteLine($"{cases.Length-failures}/{cases.Length} fake UI/discovery checks passed; no native/runtime/device proof.");return failures==0?0:1;
static Task Run(Action f){f();return Task.CompletedTask;}
static string Embedded(string name){using var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream(name)??throw new Exception("Actual selected native source resource missing.");using var reader=new StreamReader(stream);return reader.ReadToEnd();}
static void Check(bool value){if(!value)throw new Exception("Synthetic assertion failed");}
static void Reject(Action f){try{f();}catch(Exception e)when(e is InvalidDataException or InvalidOperationException or OperationCanceledException){return;}throw new Exception("Expected rejection");}
static async Task Rejected(Task t){try{await t;}catch(Exception e)when(e is IOException or InvalidOperationException or OperationCanceledException){return;}throw new Exception("Expected rejection");}
static LinuxHostPinPresentation Pin()=>new(Guid.NewGuid(),Guid.NewGuid().ToString("D"),"Synthetic computer","123456",Convert.ToBase64String(new byte[16]),"::",40002,DateTimeOffset.UtcNow.AddSeconds(100));
static LinuxHostNetworkPresentation Share()=>new(Guid.NewGuid().ToString("D"),"Synthetic computer","::",40001,320,240,2,DateTimeOffset.UtcNow.AddMinutes(20));
static LinuxHostDiscoverySnapshot Snapshot(bool pair,LinuxHostBoundControl? control=null){var c=control??new(Guid.NewGuid(),Guid.NewGuid().ToString("D"),"Synthetic computer","Peel Pro Synthetic","::",40001,-1,-1,true,DateTimeOffset.UtcNow.AddMinutes(20));return new(Guid.NewGuid(),c,pair?new(Guid.NewGuid(),"Peel Pro Pair Synthetic","::",40002,Convert.ToBase64String(new byte[16]),DateTimeOffset.UtcNow.AddSeconds(100)):null);}
static LinuxHostDiscoveryLease Lease(bool pair,LinuxHostBoundControl? control=null)=>new(Snapshot(pair,control),TimeProvider.System,TimeSpan.FromMinutes(20),()=>true);
sealed class UI:ILinuxHostUIChannel
{
    internal bool Hold,Finished;internal int Shown;internal ulong Last;internal readonly TaskCompletionSource<bool> Release=new(TaskCreationOptions.RunContinuationsAsynchronously);
    public async Task<bool> Present(ulong epoch,ulong operation,int kind,string name,string detail,Func<Func<bool>,bool> admission){Last=operation;if(Hold)await Release.Task;return admission(()=>{Shown++;return true;});}
    public Task Dismiss(ulong e,ulong o)=>Task.CompletedTask;public Task State(ulong e,ulong revision,string t,bool p,bool s,bool stop)=>Task.CompletedTask;public Task FinishClose(ulong e){Finished=true;return Task.CompletedTask;}
}
sealed class Backend:ILinuxHostUiBackend
{
    public event Action<LinuxHostUiState>? Changed;internal int Initializes,Pairs,Shares,Stops;internal bool HoldDispose;
    internal readonly TaskCompletionSource<bool> Initialized=new(TaskCreationOptions.RunContinuationsAsynchronously),Disposing=new(TaskCreationOptions.RunContinuationsAsynchronously),Drain=new(TaskCreationOptions.RunContinuationsAsynchronously);
    public Task InitializeAfterGtkActivationAsync(){Initializes++;Changed?.Invoke(new(1,true,false,1,new(1,1,320,240,2),false,false,"Ready"));Initialized.TrySetResult(true);return Task.CompletedTask;}
    internal void Emit(long revision,bool sharing)=>Changed?.Invoke(new(revision,true,false,1,new(1,1,320,240,2),sharing,false,"Source state"));
    public Task PairAsync(CancellationToken token){Pairs++;return Task.CompletedTask;}public Task ShareAsync(CancellationToken token){Shares++;return Task.CompletedTask;}public void CancelPairing(){}public void StopHost(){Stops++;}
    public async ValueTask DisposeAsync(){Disposing.TrySetResult(true);if(HoldDispose)await Drain.Task;}
}
sealed class Avahi:ILinuxAvahiNative
{
    internal bool Auto=true,Hold,FailPair,FailUpdateOnce,FailEveryUpdate,HoldUpdate;private Action? pendingUpdate;internal int Count,Stops,Updates,ControlStops;private ulong controlId;internal ulong Last;
    private readonly Dictionary<ulong,LinuxHostUIWire.Discovery> callbacks=[];
    internal readonly TaskCompletionSource<bool> UpdateQueued=new(TaskCreationOptions.RunContinuationsAsynchronously);
    internal void CompleteUpdate(){HoldUpdate=false;var done=pendingUpdate??throw new InvalidOperationException();pendingUpdate=null;done();}
    internal readonly TaskCompletionSource<bool> Begun=new(TaskCreationOptions.RunContinuationsAsynchronously),Queued=new(TaskCreationOptions.RunContinuationsAsynchronously),Release=new(TaskCreationOptions.RunContinuationsAsynchronously);
    public async Task<int> Begin(ulong id,LinuxAvahiRecord r,LinuxHostUIWire.Discovery callback,Func<Func<int>,int> admission){Queued.TrySetResult(true);if(Hold)await Release.Task;return admission(()=>{if(FailPair&&r.Type=="_peelpair._tcp")return 0;Count++;Last=id;if(r.Type=="_peel._tcp")controlId=id;callbacks[id]=callback;Begun.TrySetResult(true);if(Auto)Ready(id);return 1;});}
    internal void Ready(ulong id)=>callbacks[id](id,1,IntPtr.Zero);
    public Task<int> Update(ulong o,ulong t,string txt,LinuxHostUIWire.Discovery callback,Func<Func<int>,int> admission)=>Task.FromResult(admission(()=>{Updates++;bool fail=FailUpdateOnce||FailEveryUpdate;FailUpdateOnce=false;if(HoldUpdate){pendingUpdate=()=>callback(t,fail?0:1,IntPtr.Zero);UpdateQueued.TrySetResult(true);}else callback(t,fail?0:1,IntPtr.Zero);return 1;}));
    public Task Stop(ulong id){Stops++;if(id==controlId)ControlStops++;if(callbacks.Remove(id,out var callback))callback(id,2,IntPtr.Zero);return Task.CompletedTask;}
}
